        for (unsigned int c = 0; c < 3; ++c, ++iCurrent) {
            pcMesh->mFaces[i].mIndices[c] = iCurrent;

            // Read vertices
            aiVector3D &vec = pcMesh->mVertices[iCurrent];
            uint32_t index = pcTriangles->INDEXES[c];
            if (index >= pcSurfaces->NUM_VERTICES) {
