        for (unsigned int a = 0; a < 3; ++a) {
            for (unsigned int m = 0; m < 3; ++m) {
                nd->mTransformation[m][a] = pcTags->orientation[a][m];
                AI_SWAP4(nd->mTransformation[m][a]);
            }
        }
    }
}

